"use strict";self.onmessage=function(e){if(!e.data||typeof e.data!="object")return;const{id,action,payload}=e.data;try{switch(action){case"filter":{const{packets,filters}=payload||{},result=filterPackets(packets||[],filters||{});self.postMessage({id,action,success:!0,result});break}case"stats":{const{packets}=payload||{},stats=computePacketStats(packets||[]);self.postMessage({id,action,success:!0,result:stats});break}case"ping":{self.postMessage({id,action,success:!0,result:"pong"});break}default:self.postMessage({id,action,success:!1,error:`Acción desconocida: ${action}`})}}catch(err){self.postMessage({id,action,success:!1,error:err&&err.message?err.message:String(err)})}};function filterPackets(packets,filters){const dirFilter=(filters.dirFilter||"").toLowerCase().trim(),typeFilter=(filters.typeFilter||"").toUpperCase().trim(),searchQuery=(filters.searchQuery||"").toLowerCase().trim();return packets.filter(pkt=>{if(!pkt||typeof pkt!="object"||dirFilter&&(pkt.direction||"").toLowerCase()!==dirFilter||typeFilter&&!(pkt.packet_type||"").toUpperCase().includes(typeFilter))return!1;if(searchQuery){const sSender=pkt.sender||"",sSenderName=pkt.sender_name||"",sTarget=pkt.target||"",sText=pkt.text||"",sType=pkt.packet_type||"";if(!`${sSender} ${sSenderName} ${sTarget} ${sText} ${sType}`.toLowerCase().includes(searchQuery))return!1}return!0})}function computePacketStats(packets){let rxCount=0,txCount=0,totalBytes=0,sumSnr=0,countSnr=0,sumRssi=0,countRssi=0;const types={};for(let i=0;i<packets.length;i++){const pkt=packets[i];if(!pkt)continue;const dir=(pkt.direction||"").toLowerCase();dir==="rx"?rxCount++:dir==="tx"&&txCount++,typeof pkt.size_bytes=="number"&&(totalBytes+=pkt.size_bytes),typeof pkt.snr=="number"&&!isNaN(pkt.snr)&&(sumSnr+=pkt.snr,countSnr++),typeof pkt.rssi=="number"&&!isNaN(pkt.rssi)&&(sumRssi+=pkt.rssi,countRssi++);const type=(pkt.packet_type||"UNKNOWN").toUpperCase();types[type]=(types[type]||0)+1}return{totalPackets:packets.length,rxCount,txCount,totalBytes,avgSnr:countSnr>0?+(sumSnr/countSnr).toFixed(2):null,avgRssi:countRssi>0?+(sumRssi/countRssi).toFixed(1):null,byType:types}}
